package com.fasterxml.jackson.databind.deser;

import com.fasterxml.jackson.annotation.ObjectIdGenerator.IdKey;
import com.fasterxml.jackson.annotation.ObjectIdGenerator;
import com.fasterxml.jackson.annotation.ObjectIdResolver;
import com.fasterxml.jackson.annotation.SimpleObjectIdResolver;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.AnnotationIntrospector;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.cfg.HandlerInstantiator;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId;
import com.fasterxml.jackson.databind.introspect.Annotated;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map.Entry;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class DefaultDeserializationContext_keyDeserializerInstance_TriageGen0Test {

    @Mock
    private DeserializerFactory _df;
    @Mock
    private DeserializationConfig _config;
    @Mock
    private Annotated _ann;
    @Mock
    private JsonParser _jp;
    @Mock
    private InjectableValues _values;
    @Mock
    private HandlerInstantiator _hi;

    private DefaultDeserializationContext _context;

    // Mock implementations for testing
    static class MockKeyDeserializer implements KeyDeserializer {
        @Override
        public Object deserializeKey(String key, DeserializationContext ctxt) throws IOException {
            return key;
        }
    }

    static class MockResolvableKeyDeserializer extends MockKeyDeserializer implements ResolvableDeserializer {
        boolean resolved = false;
        @Override
        public void resolve(AnnotatedAnnotationIntrospector introspector) {
            this.resolved = true;
        }
    }

    // Helper to bypass protected constructor visibility if necessary, 
    // but here we use the provided constructor signatures via reflection or mock if needed.
    // Since we are testing DefaultDeserializationContext, we'll use a subclass or reflection to instantiate.

    private DefaultDeserializationContext createContext() {
        // Using a subclass to expose the protected constructor for testing purposes
        return new DefaultDeserializationContext(_df, null) {
            // This is a trick to allow us to set the private _config field via reflection if needed,
            // but since we are writing a professional test, we will use reflection to inject the mock _config.
        };
    }

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);

        // We need to instantiate the context. Since the constructor is protected, 
        // we use a test-subclass.
        _context = new TestableDefaultDeserializationContext(_df, _config, _jp, _values);

        // Inject the mock config into the context via reflection because it's a private field in Jackson
        java.lang.reflect.Field configField = DefaultDeserializationContext.class.getDeclaredField("_config");
        configField.setAccessible(true);
        configField.set(_context, _config);
    }

    private static class TestableDefaultDeserializationContext extends DefaultDeserializationContext {
        public TestableDefaultDeserializationContext(DeserializerFactory df, DeserializationConfig config, JsonParser jp, InjectableValues values) {
            super(null, config, jp, values);
        }
    }

    @Test
    public void testKeyDeserializerInstance_deserDefNull() throws JsonMappingException {
        assertNull(_context.keyDeserializerInstance(_ann, null));
    }

    @Test
    public void testKeyDeserializerInstance_isAlreadyKeyDeserializer() throws JsonMappingException {
        KeyDeserializer deser = new MockKeyDeserializer();
        KeyDeserializer result = _context.keyDeserializerInstance(_ann, deser);
        assertSame(deser, result);
    }

    @Test(expected = IllegalStateException.class)
    public void testKeyDeserializerInstance_invalidType() throws JsonMappingException {
        _context.keyDeserializerInstance(_ann, "NotAClassOrDeserializer");
    }

    @Test
    public void testKeyDeserializerInstance_isKeyDeserializerNone() throws JsonMappingException {
        assertNull(_context.keyDeserializerInstance(_ann, KeyDeserializer.None.class));
    }

    @Test(expected = IllegalStateException.class)
    public void testKeyDeserializerInstance_notAssignableToKeyDeserializer() throws JsonMappingException {
        _context.keyDeserializerInstance(_ann, String.class);
    }

    @Test
    public void testKeyDeserializerInstance_viaHandlerInstantiator() throws JsonMappingException {
        when(_config.getHandlerInstantiator()).thenReturn(_hi);
        KeyDeserializer mockDeser = new MockKeyDeserializer();
        when(_hi.keyDeserializerInstance(eq(_config), eq(_ann), eq(MockKeyDeserializer.class))).thenReturn(mockDeser);

        KeyDeserializer result = _context.keyDeserializerInstance(_ann, MockKeyDeserializer.class);
        assertSame(mockDeser, result);
    }

    @Test
    public void testKeyDeserializerInstance_viaClassUtilCreateInstance() throws JsonMappingException {
        when(_config.getHandlerInstantiator()).thenReturn(null);
        when(_config.canOverrideAccessModifiers()).thenReturn(true);

        KeyDeserializer result = _context.keyDeserializerInstance(_ann, MockKeyDeserializer.class);
        assertNotNull(result);
        assertTrue(result instanceof MockKeyDeserializer);
    }

    @Test
    public void testKeyDeserializerInstance_resolvableDeserializer() throws JsonMappingException {
        when(_config.getHandlerInstantiator()).thenReturn(null);
        when(_config.canOverrideAccessModifiers()).thenReturn(true);

        MockResolvableKeyDeserializer resolvable = new MockResolvableKeyDeserializer();
        // We need to force the context to return our specific instance. 
        // Since the method creates a new instance via ClassUtil, we can't easily inject it 
        // unless we mock ClassUtil (which is static) or mock the handler instantiator.

        when(_config.getHandlerInstantiator()).thenReturn(_hi);
        when(_hi.keyDeserializerInstance(any(), any(), any())).thenReturn(resolvable);

        KeyDeserializer result = _context.keyDeserializerInstance(_ann, MockKeyDeserializer.class);

        assertSame(resolvable, result);
        assertTrue("Should have called resolve()", resolvable.resolved);
    }

    @Test
    public void testKeyDeserializerInstance_handlerReturnsNullThenCreatesInstance() throws JsonMappingException {
        when(_config.getHandlerInstantiator()).thenReturn(_hi);
        when(_hi.keyDeserializerInstance(any(), any(), any())).thenReturn(null);
        when(_config.canOverrideAccessModifiers()).thenReturn(true);

        KeyDeserializer result = _context.keyDeserializerInstance(_ann, MockKeyDeserializer.class);
        assertNotNull(result);
        assertTrue(result instanceof MockKeyDeserializer);
    }
}
